"""aoe2_de.yaml is generated by gen_de.py from aoe2_hd.yaml. The DE set must not
drift from the HD set when only the HD spec is edited."""
import unittest

from polyhost.res.overlay_sources.aoe2 import gen_de


class Aoe2DeSpecTest(unittest.TestCase):

    def test_the_committed_de_spec_matches_gen_de(self):
        committed = (gen_de.HERE / "aoe2_de.yaml").read_text(encoding="utf-8")
        self.assertEqual(committed, gen_de.render(),
                         "aoe2_de.yaml is stale: run "
                         "python polyhost/res/overlay_sources/aoe2/gen_de.py")


if __name__ == "__main__":
    unittest.main()
